import{_ as e,o as i,c as s,a6 as t}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Descargas y actualizaciones","description":"","frontmatter":{"title":"Descargas y actualizaciones","docId":"user.start.updates","translationKey":"user.start.updates","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6b92351b3ee8eb1b0745db65bbddb3eab21f4ae0a9945795c94147c9ca347e73","translationRevision":"98a7c2cfe052496880550d587bd75ee988e03d0ac01aa3ac71d3c769b7b0814e","order":40},"headers":[],"relativePath":"es/user/updates.md","filePath":"es/user/updates.md","lastUpdated":1794611623000}'),l={name:"es/user/updates.md"};function o(r,a,n,c,d,u){return i(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="downloads-and-updates" tabindex="-1">Descargas y actualizaciones <a class="header-anchor" href="#downloads-and-updates" aria-label="Permalink to &quot;Descargas y actualizaciones {#downloads-and-updates}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Elegir el canal correcto y actualizar sin confundir la búsqueda de versiones con una instalación automática. Cierra las sesiones activas y respalda los datos locales antes de cambiar de versión, especialmente si sus notas documentan una migración de base de datos.</p><h2 id="select-a-channel" tabindex="-1">Elige un canal <a class="header-anchor" href="#select-a-channel" aria-label="Permalink to &quot;Elige un canal {#select-a-channel}&quot;">​</a></h2><p>La <a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">lista de versiones</a> distingue versiones estables y preliminares. Un candidato como <code>-rc</code> sirve para verificación. El actualizador distingue los feeds estable y beta y autentica sus metadatos firmados antes de ofrecer una versión. Un JSON sin firma o un instalador modificado no constituye una actualización válida.</p><h2 id="check-and-install" tabindex="-1">Buscar e instalar <a class="header-anchor" href="#check-and-install" aria-label="Permalink to &quot;Buscar e instalar {#check-and-install}&quot;">​</a></h2><ol><li>Abre <strong>Settings → General</strong> y comprueba la versión instalada y el estado del actualizador.</li><li>Ejecuta la comprobación disponible. Si la compilación no configura la clave pública o el feed, mostrará que esa capacidad no está disponible.</li><li>Lee las notas y elige el paquete de tu plataforma.</li><li>Sigue la descarga o instalación manual que ofrezca tu compilación. El workflow habilita comprobaciones autenticadas solo si está configurada la variable de clave pública; la instalación automática tiene puertas adicionales.</li><li>Para actualizar manualmente, cierra TikTools, instala o sustituye el paquete completo verificado y vuelve a abrirlo. Conserva los datos fuera de los archivos de la aplicación.</li></ol><h2 id="expected-result" tabindex="-1">Resultado esperado <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Resultado esperado {#expected-result}&quot;">​</a></h2><p>La aplicación reiniciada informa de la versión elegida y abre el perfil local esperado. Los ZIP/TAR portátiles requieren sustitución manual. Un ejecutable extraído o una instalación no reconocida también puede requerir ese procedimiento aunque exista un instalador AppImage.</p><h2 id="recovery-and-limitations" tabindex="-1">Recuperación y límites <a class="header-anchor" href="#recovery-and-limitations" aria-label="Permalink to &quot;Recuperación y límites {#recovery-and-limitations}&quot;">​</a></h2><p>Una firma inválida significa que la actualización falló: descarga una copia oficial nueva y verifica sus checksums. No omitas la verificación. El reemplazo automático de AppImage y la entrega a NSIS tienen gates de compilación separados y son experimentales. No existe un rollback automático general. Volver a un binario anterior no deshace una migración SQLite.</p><p>Reporta la versión, el formato del paquete y el error del actualizador desde Diagnostics. No adjuntes claves de firma, tokens de invitación ni datos de cuenta. La <a href="./installation.html">guía de instalación</a> describe los formatos compatibles.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>La capacidad del updater se fija al compilar. Comprobar requiere feed y clave pública. AppImage automático exige además puerta común de instalación y origen compatible detectado; NSIS exige esa misma puerta Y la específica NSIS. Variables de entorno después de instalar no habilitan puertas compiladas. Portable/extraído/desconocido usa reemplazo manual. Verifica versión, reinicio y perfil tras instalar; descarga, checksum o lanzar instalador no prueban finalización.</p>',14)])])}const b=e(l,[["render",o]]);export{m as __pageData,b as default};
